"""Explicit storefront labels for the 30 locales.

German main names follow the live catalog. Textile leaves replace the Turkish
source words so a German page does not show Turkish, and a Turkish page does
not show German. Country names cover every country in the selector, including
the 27 EU members.
"""

LOCALES = [
    "de", "en", "tr", "ar", "fr", "nl", "bg", "hr", "el", "cs", "da", "et", "fi",
    "hu", "it", "lv", "lt", "lb", "mt", "pl", "pt", "ro", "sk", "sl", "es", "ca",
    "eu", "gl", "sv", "ga",
]


def L(*values):
    if len(values) != len(LOCALES):
        raise SystemExit(f"expected {len(LOCALES)} labels, got {len(values)}: {values[:3]}")
    return dict(zip(LOCALES, values))


